INSERT INTO `settings` VALUES (22, 'Config\\App', 'emailUploadDocument', '<figure class=\"table\"><table><tbody><tr><td rowspan=\"2\"><strong>{logo}</strong></td><td><strong>KEMENTERIAN HUKUM DAN HAK ASASI MANUSIA REPUBLIK INDONESIA&nbsp;</strong><br><strong>DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL</strong></td></tr><tr><td>Jl. H.R. Rasuna Said Kav 8-9, Jakarta Selatan 12190, Telepon: (021) 57905609 Faksimili: (021) 57905609&nbsp;</td></tr><tr><td colspan=\"2\">&lt;hr&gt;</td></tr><tr><td colspan=\"2\">Yth,<br><strong>{username}</strong>,</td></tr><tr><td colspan=\"2\"><p>Selamat datang di Aplikasi Sistem Administrasi Pelayanan Perjalanan Dinas Luar Negeri (SIDILAN).<br>Anda tercatat sebagai calon delegasi Perjalanan Dinas ke Luar Negeri, oleh karena itu mohon untuk unggah dokumen persyaratan Perjalanan Dinas dengan klik&nbsp;</p><p><strong>URL: </strong><a href=\"{url}\"><strong>{url}</strong></a></p><p>Selanjutnya petugas aplikasi akan melakukan verifikasi dokumen Anda.</p><p>Jika ada pertanyaan lebih lanjut, silahkan menghubungi:<br>Whatsapp <a href=\"\">089623636142</a></p></td></tr><tr><td colspan=\"2\">Hormat kami,<br><br><strong>Direktorat Jenderal Kekayaan Intelektual</strong></td></tr></tbody></table></figure><p><br><br>&nbsp;</p>', 'string', NULL, 'Template', '2023-09-14 17:16:20', '2023-09-15 01:29:47');
