INSERT INTO `t_berita` VALUES (11, 'Sharing Knowledge dan Benchmarking ke Perpustakaan UI, Depok', 'sharing-knowledge-dan-benchmarking-ke-perpustakaan-ui-depok', 'Tanggal 11 September, Perpustakaan Pusat LAN berkesempatan untuk sharing knowledge dan benchmarking dengan Perpustakaan UI, Depok terkait Pengelolaan dan Pemanfaatan Repositori Institusi. Repositori Institusi sangat bermanfaat untuk menghimpun (mengoleksi) karya yang dihasilkan institusi, menyimpan dan melestarikan karya agar tetap terjaga mutu fisik dan isinya, memfasilitasi pemanfaatan untuk pendidikan, penelitian, pengembangan ilmu, penyebaran informasi, terintegrasi dengan sistem antar institus agar interoperabilitas data.', '20251020_1760946977_74dc929933cb86d89780.jpeg', 0, 'wdk', 3, 1, NULL, '', 1, 1, '2025-08-07 10:28:30', '2026-05-25 14:00:44', '20251020_1760946977_dd0eb099bbac7ad0fa0b.jpeg');
