INSERT INTO `t_template` VALUES (1, NULL, 'Kartu Depan Lanscape - Qrcode - With Header', 'template-1', NULL, 'Landscape', 'Depan', 'landscape', 'Template Depan Landscape 1', '<div class=\"container-card\" style=\"width: 1004px; height: 550px; background-image: url(\'{perpus_bg}\'); background-repeat: no-repeat; font-family: Arial, Helvetica, sans-serif; padding: 20px; box-sizing: border-box;\">\r\n<table style=\"width: 100%; height: 100%; border-collapse: collapse;\">\r\n<tbody>\r\n<tr><!-- KIRI: logo + nama -->\r\n<td style=\"width: 60%; vertical-align: top; text-align: center;\">\r\n<div style=\"font-size: 30pt; font-weight: bold; color: #ffcc00; text-shadow: #000000 1px 1px; text-align: left;\"><span style=\"font-size: 20pt;\"><span style=\"font-size: 12pt;\">{perpus_nama}</span></span></div>\r\n<div style=\"font-size: 30pt; font-weight: bold; color: #ffcc00; text-shadow: 1px 1px #000;\"><span style=\"font-size: 20pt; color: #000000;\">{anggota_nama}</span></div>\r\n<div style=\"font-size: 30pt; font-weight: bold; color: #ffcc00; text-shadow: 1px 1px #000;\"><span style=\"font-size: 20pt; color: #000000;\">{anggota_qrcode}</span></div>\r\n</td>\r\n<!-- KANAN: jenis anggota, nomor, berlaku, foto -->\r\n<td style=\"width: 40%; vertical-align: top; text-align: center;\">\r\n<div style=\"background-color: black; color: white; font-size: 16pt; font-weight: bold; padding: 5px 10px; display: inline-block; margin-bottom: 10px;\">{anggota_jenis}</div>\r\n<div style=\"font-size: 22pt; font-weight: bold; margin-bottom: 10px;\">{anggota_nomor}</div>\r\n<div style=\"font-size: 14pt; margin-bottom: 10px;\">Berlaku hingga<br />12-03-2000</div>\r\n<div>{anggota_foto}</div>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>', '1751183964_9a259cf07c9ddfa7fcf0.jpg', '1,844.714', 1, 1, 1, '2022-12-05 18:56:10', '2025-07-28 17:16:29', NULL);
INSERT INTO `t_template` VALUES (3, NULL, 'Template 3', 'template-3', NULL, 'Kartu', 'Kartu Depan', 'Landscape', 'Template Depan Landscape', '<div class=\"container-card\" style=\"background-image: url(\'{perpus_bg}\'); background-repeat: no-repeat;\">\r\n<table style=\"border-collapse: collapse; width: 1004px; height: 618px; font-family: arial, helvetica, sans-serif;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"height: 180px;\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 100%;\">\r\n<table style=\"border-collapse: collapse; width: 100%; font-weight: bold;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 25%; text-align: right; padding-right: 30px;\">{anggota_foto}</td>\r\n<td style=\"width: 75%; text-align: left; font-size: 18pt;\">\r\n<table style=\"width: 100%;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 30%; padding: 10px;\">Nomor</td>\r\n<td style=\"width: 2%; padding: 10px;\">:</td>\r\n<td style=\"width: 68%; padding: 10px;\">{anggota_nomor}</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 30%; padding: 10px;\">Nama</td>\r\n<td style=\"width: 2%; padding: 10px;\">:</td>\r\n<td style=\"width: 68%; padding: 10px;\">{anggota_nama}</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 30%; padding: 10px;\">Jenis Anggota</td>\r\n<td style=\"width: 2%; padding: 10px;\">:</td>\r\n<td style=\"width: 68%; padding: 10px;\">{anggota_jenis}</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 100%; height: 180px; text-align: center; padding: 5px;\">{anggota_barcode}</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>', 'card-3.png', '576 x 366', 0, 1, 1, '2022-12-12 10:08:46', '2023-06-08 10:59:33', NULL);
INSERT INTO `t_template` VALUES (4, NULL, 'Template 4', 'template-4', NULL, 'Kartu', 'Kartu Depan', 'Potrait', 'Template Depan Potrait', '<div class=\"container-card\" style=\"background-image: url(\'{perpus_bg}\'); background-repeat: no-repeat;\">\r\n<table style=\"border-collapse: collapse; width: 618px; height: 1004px; font-family: arial, helvetica, sans-serif;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"height: 300px;\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 100%; text-align: center;\">{anggota_foto}</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 100%; text-align: center; margin-top: 50px;\">{anggota_nama}</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 100%; text-align: center;\">{anggota_nomor}</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 100%; text-align: center;\">{anggota_jenis}</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 100%; text-align: center;\">{anggota_qrcode}</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>', 'card-3.png', '366 x 576', 0, 1, 1, '2022-12-26 09:46:11', '2023-06-08 11:25:07', NULL);
