INSERT INTO `t_template` VALUES (6, NULL, 'Surat Keterangan Bebas Pustaka', 'surat-keterangan-bebas-pustaka', NULL, 'Surat', 'Surat Keterangan', 'Potrait', 'Surat Keterangan Bebas Pustaka', '<table style=\"border-collapse: collapse; width: 100%; height: 416px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 72px;\">\r\n<td style=\"text-align: justify; height: 72px; width: 100%;\" colspan=\"3\">\r\n<table style=\"border-collapse: collapse; width: 99.1114%;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 15%; text-align: left;\">&nbsp;</td>\r\n<td style=\"width: 70%; text-align: center;\"><span style=\"font-size: 36px;\"><strong>SURAT KETERANGAN BEBAS PUSTAKA</strong></span></td>\r\n<td style=\"width: 15%; text-align: right;\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 72px;\">\r\n<td style=\"text-align: justify; height: 72px; width: 100%;\" colspan=\"3\">\r\n<p>Saya yang bertanda tangan di bawah ini menerangkan bahwa:</p>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 108px;\">\r\n<td style=\"text-align: justify; width: 100%; height: 108px;\" colspan=\"3\">\r\n<table style=\"border-collapse: collapse; width: 99.1114%;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 14.4951%;\">Nama Anggota</td>\r\n<td style=\"width: 1.08942%;\">:</td>\r\n<td style=\"width: 84.3742%;\">$anggota_nama</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 14.4951%;\">Jenis Anggota</td>\r\n<td style=\"width: 1.08942%;\">:</td>\r\n<td style=\"width: 84.3742%;\">$anggota_jenis</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 14.4951%;\">No. Identitas / KTP</td>\r\n<td style=\"width: 1.08942%;\">:</td>\r\n<td style=\"width: 84.3742%;\">$anggota_nomor</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 14.4951%;\">Fakultas</td>\r\n<td style=\"width: 1.08942%;\">:</td>\r\n<td style=\"width: 84.3742%;\">$anggota_fakultas</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 14.4951%;\">Kelas</td>\r\n<td style=\"width: 1.08942%;\">:</td>\r\n<td style=\"width: 84.3742%;\">$anggota_kelas</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 14.4951%;\">Alamat</td>\r\n<td style=\"width: 1.08942%;\">:</td>\r\n<td style=\"width: 84.3742%;\">$anggota_alamat</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 72px;\">\r\n<td style=\"text-align: justify; height: 72px; width: 100%;\" colspan=\"3\">\r\n<p>Telah terbebas dari tunggakan peminjaman koleksi di $perpus_nama.</p>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 22px;\">\r\n<td style=\"width: 100%; text-align: justify; height: 22px;\" colspan=\"3\">\r\n<p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 238px;\">\r\n<td style=\"width: 40.0328%; height: 126px;\">&nbsp;</td>\r\n<td style=\"width: 20.0164%; height: 126px;\">&nbsp;</td>\r\n<td style=\"width: 39.9508%; height: 126px;\">\r\n<p>$surat_tanggal,<br /><br /><br /><br /><br /><br /></p>\r\n<p><strong>$anggota_nama</strong><br />$anggota_nomor</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, NULL, 0, 1, 1, '2023-06-02 11:32:18', '2023-06-03 06:02:48', NULL);
